//! 🎯️ Variant selection retains actual original discriminators and bounded schema comparisons, below the receive trait.
use crate::{NativeDecodeControl,OriginalReceivingPrimary,RetainedWorkOutcome,RetirementDemand,RetainedCloneGrant,RetainedCloneProgress,RetainedCloneStep,ValueError,retained_clone::{RetainedCloneBinding,RetainedCloneClose,RetainedCloneRef,retained_clone_grant_admits},native_close_settle,NativeRecordKey,NativeRecordMatcher,NativeRecordSchema,NativeSchemaFields,NativeSchemaLeaf,NativeSchemaKeySource,NativeFieldMatch,tree::{NativeValueSource,NativeTreeKind,fixed,receipt,invalid,nested,child_grant}};
use crate::native_decoding::{OriginalEffectReply,OriginalEffectReplyComplete};
#[derive(Clone,Copy)]pub struct NativeVariantSpec{pub all:NativeSchemaFields,pub units:NativeSchemaFields,pub data:NativeSchemaFields,pub statements:NativeSchemaFields,pub count:usize,pub tag:Option<NativeSchemaFields>}
#[derive(Clone,Copy,Debug,PartialEq,Eq)]pub struct NativeVariantSelection{pub index:usize,pub direct:bool}
pub struct NativeVariantSelector<I:NativeValueSource+?Sized>{binding:Option<RetainedCloneBinding>,matcher:Option<NativeRecordMatcher<I>>,spec:NativeVariantSpec,selection:Option<NativeVariantSelection>,tag:Option<usize>,scan:usize,phase:u8,direct:bool,closing:bool,failed:bool}
impl<I:NativeValueSource+?Sized>NativeVariantSelector<I>{
 pub fn new(spec:NativeVariantSpec)->Self{Self{binding:None,matcher:None,spec,selection:None,tag:None,scan:0,phase:0,direct:false,closing:false,failed:false}}
 pub fn result(&self)->Option<NativeVariantSelection>{self.selection}
 pub fn validate_input(&self,input:RetainedCloneRef<'_,I>)->Result<(),ValueError>{input.check_binding(&self.binding)?;Ok(())}
 pub fn demands(&self,input:RetainedCloneRef<'_,I>,body:usize,maximum_work_units:u64)->Result<RetirementDemand,ValueError>{if self.closing{return Err(invalid())}if self.selection.is_some()||self.failed{return Ok(Default::default())}if !input.check_binding(&self.binding)?{return Ok(fixed(input.binding_copy_bytes()))}if let Some(matcher)=self.matcher.as_ref(){if self.phase==3{return self.settlement_demand(body)}if matcher.result().is_none(){return nested(matcher.demands(input,body,maximum_work_units)?,0)}}Ok(fixed(0))}
 /// 🎯️ Resolves the variant straight from a plain-leaf schema and an ordinal-keyed or text source in one inline action; any other shape keeps the matcher path.
 fn direct_probe(&self,input:RetainedCloneRef<'_,I>)->Result<Option<(NativeVariantSelection,u64)>,ValueError>{
  let source=input.get();if source.variant_tag().is_some(){return Ok(None)}
  let named=|fields:NativeSchemaFields,name:&str|->Option<usize>{for index in 0..self.spec.count{match fields.entry(index){Some(NativeRecordSchema::Leaf(leaf))if leaf.name==name=>return Some(leaf.ordinal as usize),Some(NativeRecordSchema::Leaf(_))|Some(NativeRecordSchema::Skip)=>{},_=>return None}}None};
  let(name,work)=if let Some(tag)=self.spec.tag{
   let Some(NativeRecordSchema::Leaf(leaf))=tag.entry(0)else{return Ok(None)};if tag.entry(1).is_some(){return Ok(None)}
   let count=source.record_len()?;let mut found=None;
   for index in 0..count{match source.record_key(index)?{NativeRecordKey::Ordinal(ordinal)=>{if u32::from(ordinal)==leaf.ordinal{if found.is_some(){return Ok(None)}found=Some(index)}},_=>return Ok(None)}}
   let Some(at)=found else{return Ok(None)};let Ok(text)=source.record_child(at).and_then(|child|child.text())else{return Ok(None)};(text.as_str(),1+count as u64)
  }else if source.tree_kind()==Some(NativeTreeKind::Text){let Ok(text)=source.text()else{return Ok(None)};(text.as_str(),2)}else{return Ok(None)};
  let fields=if self.spec.tag.is_some(){self.spec.all}else{self.spec.units};
  Ok(named(fields,name).filter(|index|*index<self.spec.count).map(|index|(NativeVariantSelection{index,direct:false},work)))
 }
 /// 🧭️ Selects the resident matcher or the one separately funded local selector action.
 pub fn select_advance(&self,input:RetainedCloneRef<'_,I>,body:usize,maximum_work_units:u64)->Result<crate::NativeAdvanceSelection,ValueError>{
  if self.closing||self.failed||self.selection.is_some(){return Err(invalid())}
  let work=if !input.check_binding(&self.binding)?{input.binding_work_demand(&self.binding)?}else if let Some(matcher)=self.matcher.as_ref(){if self.phase==3{self.settlement_work_demand(body)?}else if matcher.result().is_none(){return matcher.select_advance(input,body,maximum_work_units)}else{1}}else if self.phase==1{self.direct_probe(input)?.map_or(1,|(_,work)|work)}else{1};
  if work>maximum_work_units{return Err(ValueError::literal(crate::ValueRefusalKind::WorkLimit,"native variant action exceeds its original work ceiling"))}Ok(crate::NativeAdvanceSelection::Local{work})
 }
 /// ⏲️ Quotes the matcher Work selected beneath this variant's original discriminator.
 pub fn advance_work_demand(&self,input:RetainedCloneRef<'_,I>,body:usize)->Result<u64,ValueError>{
  match self.select_advance(input,body,u64::MAX)?{
   crate::NativeAdvanceSelection::Local{work}=>Ok(work),
   crate::NativeAdvanceSelection::Nested=>self.matcher.as_ref().ok_or_else(invalid)?.nested_work_demand(input),
  }
 }
 /// 🪢️ Polls only the resident record matcher.
 pub fn advance_nested(&mut self,input:RetainedCloneRef<'_,I>,control:&mut NativeDecodeControl<'_>,witness:semio_framework_value_control_contract::OriginalSourceTurnWitness<'_>,body:usize,maximum_work_units:u64,g:RetainedCloneGrant)->crate::RetainedWorkPoll<RetainedCloneStep,crate::native_decoding::NativeReceivingFailure>{
  match self.matcher.as_mut(){Some(matcher) if self.phase!=3&&matcher.result().is_none()=>matcher.advance_nested(input,control,witness,body,maximum_work_units,child_grant(g,0)).map(|s|RetainedCloneStep::Progress(s.progress())),_=>crate::RetainedWorkPoll::Complete(RetainedWorkOutcome{result:Err(invalid().into()),work:0})}
 }
 /// 📬️ Records one local selector or matcher action into the borrowed original reply; the caller passes a progress-normalized reply.
 pub fn advance_local<'r>(&mut self,input:RetainedCloneRef<'_,I>,body:usize,effect:&mut crate::RetainedAllocationEffect<'_>,reply:OriginalEffectReply<'r,RetainedCloneStep,OriginalReceivingPrimary>)->Result<OriginalEffectReplyComplete<'r,RetainedCloneStep,OriginalReceivingPrimary>,ValueError>{
  let d=self.demands(input,body,effect.maximum_work_units())?;if !retained_clone_grant_admits(effect.grant(),d){return Ok(reply.complete(Ok(RetainedCloneStep::Progress(Default::default()))))}
  if self.binding.is_none(){let turn=input.bind(&mut self.binding,effect);return Ok(reply.complete(turn.result.map(|p|RetainedCloneStep::Progress(p.unwrap_or_default())).map_err(Into::into)))}
  if self.phase==3&&self.matcher.is_some(){return self.settle_into(effect,reply)}
  if self.phase==1&&self.matcher.is_none(){if let Some((selection,work))=self.direct_probe(input)?{if !effect.performed(work)?{return Ok(reply.complete(Err(ValueError::literal(crate::ValueRefusalKind::WorkLimit,"native variant action exceeded its original work").into())))}self.selection=Some(selection);self.phase=5;return Ok(reply.complete(Ok(RetainedCloneStep::Complete(receipt(fixed(0))))))}}
  let g=effect.grant();if let Some(matcher)=self.matcher.as_mut().filter(|matcher|matcher.result().is_none()){return matcher.advance_local(input,body,&mut effect.nested(child_grant(g,0)),reply)}
  if !effect.performed(1)?{return Ok(reply.complete(Err(ValueError::literal(crate::ValueRefusalKind::WorkLimit,"native variant action exceeded its original work").into())))}
  let result:Result<(),OriginalReceivingPrimary>=(||{match self.phase{
   0=>self.phase=1,
   1=>{if input.get().variant_tag().is_some(){self.direct=true;self.matcher=Some(NativeRecordMatcher::new(self.spec.statements,self.spec.count,NativeSchemaKeySource::VariantTag));self.phase=4;}else if self.spec.tag.is_some(){self.phase=2;}else if input.get().tree_kind()==Some(NativeTreeKind::Text){self.matcher=Some(NativeRecordMatcher::new(self.spec.units,self.spec.count,NativeSchemaKeySource::Text));self.phase=4;}else if input.get().tree_kind().is_none(){self.matcher=Some(NativeRecordMatcher::new(self.spec.units,self.spec.count,NativeSchemaKeySource::EnumOrdinal));self.phase=4;}else{if input.get().record_len()?!=1{return Err(invalid().into())}self.matcher=Some(NativeRecordMatcher::new(self.spec.data,self.spec.count,NativeSchemaKeySource::RecordName(0)));self.phase=4;}},
   2=>{if let Some(matcher)=self.matcher.as_mut(){match matcher.result().ok_or_else(invalid)?{NativeFieldMatch::Field(_)=>{if self.tag.is_some(){self.failed=true;return Err(invalid().with_retained_progress(receipt(fixed(0))).into())}self.tag=Some(self.scan);},NativeFieldMatch::Ambiguous=>{self.failed=true;return Err(invalid().with_retained_progress(receipt(fixed(0))).into())},NativeFieldMatch::Missing=>{}}self.phase=3;}else{let count=input.get().record_len()?;if self.scan==count{let tag=self.tag.ok_or_else(invalid)?;self.matcher=Some(NativeRecordMatcher::new(self.spec.all,self.spec.count,NativeSchemaKeySource::RecordText(tag)));self.phase=4;}else{self.matcher=Some(NativeRecordMatcher::new(self.spec.tag.ok_or_else(invalid)?,1,NativeSchemaKeySource::Record(self.scan)));}}},
   3=>{self.matcher=None;self.scan+=1;self.phase=2;},
   4=>{let NativeFieldMatch::Field(index)=self.matcher.as_ref().ok_or_else(invalid)?.result().ok_or_else(invalid)?else{self.failed=true;return Err(invalid().with_retained_progress(receipt(fixed(0))).into())};if index>=self.spec.count{self.failed=true;return Err(invalid().with_retained_progress(receipt(fixed(0))).into())}self.selection=Some(NativeVariantSelection{index,direct:self.direct});self.phase=5;},
   _=>return Err(invalid().into()),
  }Ok(())})();
  Ok(reply.complete(result.map(|()|if self.selection.is_some(){RetainedCloneStep::Complete(receipt(fixed(0)))}else{RetainedCloneStep::Progress(receipt(fixed(0)))})))
 }
 pub fn settlement_start_demand(&self)->RetirementDemand{self.matcher.as_ref().map_or(Default::default(),|matcher|matcher.begin_close_demand())}
 pub fn settlement_start_work_demand(&self)->u64{self.matcher.as_ref().map_or(0,|matcher|matcher.begin_close_work_demand())}
 pub fn begin_settlement_paid(&mut self,effect:&mut crate::RetainedAllocationEffect<'_>)->RetainedWorkOutcome{if let Some(matcher)=self.matcher.as_mut(){matcher.begin_close_paid(effect)}else{RetainedWorkOutcome{result:Ok(RetainedCloneStep::Complete(Default::default())),work:0}}}
 pub fn settled(&self)->bool{self.matcher.is_none()}
 pub fn settlement_demand(&self,body:usize)->Result<RetirementDemand,ValueError>{if let Some(matcher)=self.matcher.as_ref(){if matcher.terminal_is_empty(){Ok(fixed(std::mem::size_of::<Option<NativeRecordMatcher<I>>>()))}else if !matcher.close_started(){Ok(matcher.begin_close_demand())}else{nested(matcher.close_demands(body)?,0)}}else{Ok(Default::default())}}
 pub fn settlement_work_demand(&self,body:usize)->Result<u64,ValueError>{match self.matcher.as_ref(){None=>Ok(0),Some(matcher)=>if matcher.terminal_is_empty(){Ok(1)}else if !matcher.close_started(){Ok(matcher.begin_close_work_demand())}else{matcher.close_work_demand(body)}}}
 pub fn settle_step(&mut self,effect:&mut crate::RetainedAllocationEffect<'_>)->crate::OriginalRetirementPoll{use crate::RetainedWorkPoll::Complete;if self.matcher.is_none(){return Complete(RetainedWorkOutcome{result:Ok(RetainedCloneStep::Complete(Default::default())),work:0})}let g=effect.grant();let d=match self.settlement_demand(g.maximum_copy_bytes){Ok(d)=>d,Err(error)=>return Complete(RetainedWorkOutcome{result:Err(error.into()),work:0})};if !retained_clone_grant_admits(g,d){return Complete(RetainedWorkOutcome{result:Ok(RetainedCloneStep::Progress(Default::default())),work:0})}let matcher=self.matcher.as_mut().expect("retained matcher");if !matcher.close_started()&&!matcher.terminal_is_empty(){let turn=matcher.begin_close_paid(effect);return Complete(RetainedWorkOutcome{result:turn.result.map_err(Into::into),work:turn.work})}if !matcher.terminal_is_empty(){let child=child_grant(g,0);return native_close_settle(&mut effect.nested(child),|effect,reply|matcher.close_into(child.maximum_copy_bytes,effect,reply))}if effect.maximum_work_units()==0{return Complete(RetainedWorkOutcome{result:Ok(RetainedCloneStep::Progress(Default::default())),work:0})}match effect.performed(1){Ok(true)=>{},Ok(false)=>return Complete(RetainedWorkOutcome{result:Err(ValueError::literal(crate::ValueRefusalKind::WorkLimit,"variant matcher release exceeded its work authority").into()),work:1}),Err(error)=>return Complete(RetainedWorkOutcome{result:Err(error.into()),work:1})}self.matcher=None;Complete(RetainedWorkOutcome{result:Ok(RetainedCloneStep::Progress(receipt(d))),work:1})}
 /// 🧹️ Records one settlement action of the resident matcher and completes the reply once the matcher is released.
 pub fn settle_into<'r>(&mut self,effect:&mut crate::RetainedAllocationEffect<'_>,reply:OriginalEffectReply<'r,RetainedCloneStep,OriginalReceivingPrimary>)->Result<OriginalEffectReplyComplete<'r,RetainedCloneStep,OriginalReceivingPrimary>,ValueError>{
  let poll=self.settle_step(effect);Ok(match poll{crate::RetainedWorkPoll::Pending{..}=>reply.pending(),crate::RetainedWorkPoll::Complete(turn)=>reply.complete(turn.result.map(|step|if self.matcher.is_none(){RetainedCloneStep::Complete(step.progress())}else{RetainedCloneStep::Progress(step.progress())}).map_err(Into::into))})
 }
 /// ⏳️ Reports a begun original matcher action that remains unresolved.
 pub fn advance_pending(&self)->bool{self.matcher.as_ref().is_some_and(NativeRecordMatcher::advance_pending)}
 pub fn begin_close(&mut self){self.closing=true;}
 pub fn begin_close_demand(&self)->RetirementDemand{if self.closing{Default::default()}else{fixed(std::mem::size_of::<bool>())}}
 pub fn begin_close_work_demand(&self)->u64{u64::from(!self.closing)}
 pub fn begin_close_paid(&mut self,effect:&mut crate::RetainedAllocationEffect<'_>)->RetainedWorkOutcome{if self.closing{return RetainedWorkOutcome{result:Ok(RetainedCloneStep::Complete(Default::default())),work:0}}let d=self.begin_close_demand();if !retained_clone_grant_admits(effect.grant(),d)||effect.maximum_work_units()==0{return RetainedWorkOutcome{result:Ok(RetainedCloneStep::Progress(Default::default())),work:0}}match effect.performed(1){Ok(true)=>{},Ok(false)=>return RetainedWorkOutcome{result:Err(ValueError::literal(crate::ValueRefusalKind::WorkLimit,"variant close start exceeded its work authority")),work:1},Err(error)=>return RetainedWorkOutcome{result:Err(error),work:1}}self.closing=true;RetainedWorkOutcome{result:Ok(RetainedCloneStep::Complete(receipt(d))),work:1}}
 pub fn close_demands(&self,body:usize)->Result<RetirementDemand,ValueError>{if !self.closing{return Ok(self.begin_close_demand())}if self.matcher.is_some(){return self.settlement_demand(body)}if self.binding.is_some(){return RetainedCloneBinding::close_demand(&self.binding,body)}if self.phase!=6{return Ok(fixed(std::mem::size_of::<Option<NativeVariantSelection>>()+std::mem::size_of::<Option<usize>>()+std::mem::size_of::<bool>()+std::mem::size_of::<u8>()))}Ok(Default::default())}
 pub fn close_work_demand(&self,body:usize)->Result<u64,ValueError>{if !self.closing{return Ok(self.begin_close_work_demand())}if let Some(matcher)=self.matcher.as_ref(){return if !matcher.close_started(){Ok(matcher.begin_close_work_demand())}else if matcher.terminal_is_empty(){Ok(1)}else{matcher.close_work_demand(body)}}if self.binding.is_some(){return RetainedCloneBinding::close_work_demand(&self.binding,body)}Ok(u64::from(self.phase!=6))}
 fn close_dispatch<'r>(&mut self,mut original:Option<&mut crate::OriginalRetirementCloseLoan<'_>>,body:usize,effect:&mut crate::RetainedAllocationEffect<'_>,reply:crate::native_decoding::OriginalEffectReply<'r,RetainedCloneStep,crate::OriginalRetirementFailure>,recover:bool)->Result<crate::native_decoding::OriginalEffectReplyComplete<'r,RetainedCloneStep,crate::OriginalRetirementFailure>,ValueError>{
  if self.terminal_is_empty(){return Ok(reply.complete(Ok(RetainedCloneStep::Complete(Default::default()))))}
  if !self.closing{if recover{return Err(invalid())}let turn=self.begin_close_paid(effect);return Ok(reply.complete(turn.result.map_err(Into::into)))}
  if self.requires_original_birth()||(original.is_none()&&self.requires_original_control()){return Ok(reply.complete(Err(ValueError::literal(crate::ValueRefusalKind::UnsupportedOwner,"variant close requires its selected original control").into())))}
  let g=effect.grant();let d=match self.close_demands(body){Ok(d)=>d,Err(error)=>return Ok(reply.complete(Err(error.into())))};if !retained_clone_grant_admits(g,d)||effect.remaining_work_units()?==0{return Ok(reply.complete(Ok(RetainedCloneStep::Progress(Default::default()))))}
  if let Some(matcher)=self.matcher.as_mut(){
   if !matcher.terminal_is_empty()&&!matcher.close_started(){if recover{return Err(invalid())}let turn=matcher.begin_close_paid(effect);return Ok(reply.complete(turn.result.map_err(Into::into)))}
   if !matcher.terminal_is_empty(){let mut nested=effect.nested(child_grant(g,0));let route=original.as_deref_mut().filter(|_|matcher.requires_original_control());return match(route,recover){(Some(original),false)=>matcher.close_original_into(original,body,&mut nested,reply),(Some(original),true)=>matcher.recover_close_original_into(original,body,&mut nested,reply),(None,false)=>matcher.close_into(body,&mut nested,reply),(None,true)=>matcher.recover_close_into(body,&mut nested,reply)}}
   if recover{return Err(invalid())}if !effect.performed(1)?{return Ok(reply.complete(Err(ValueError::literal(crate::ValueRefusalKind::WorkLimit,"variant matcher release exceeded its work authority").into())))}self.matcher=None;return Ok(reply.complete(Ok(RetainedCloneStep::Progress(receipt(d)))))
  }
  if self.binding.is_some(){let reply=reply.progress();return match(original.as_deref_mut().filter(|_|RetainedCloneBinding::requires_original_control(&self.binding)),recover){(Some(original),false)=>RetainedCloneBinding::close_original_into(&mut self.binding,original,body,effect,reply),(Some(original),true)=>RetainedCloneBinding::recover_close_original_into(&mut self.binding,original,body,effect,reply),(None,false)=>RetainedCloneBinding::close_into(&mut self.binding,body,effect,reply),(None,true)=>RetainedCloneBinding::recover_close_into(&mut self.binding,body,effect,reply)}}
  if recover{return Err(invalid())}if !effect.performed(1)?{return Ok(reply.complete(Err(ValueError::literal(crate::ValueRefusalKind::WorkLimit,"variant close exceeded its work authority").into())))}self.selection=None;self.tag=None;self.failed=false;self.phase=6;Ok(reply.complete(Ok(RetainedCloneStep::Complete(receipt(d)))))
 }
 pub fn close_into<'r>(&mut self,body:usize,effect:&mut crate::RetainedAllocationEffect<'_>,reply:crate::native_decoding::OriginalEffectReply<'r,RetainedCloneStep,crate::OriginalRetirementFailure>)->Result<crate::native_decoding::OriginalEffectReplyComplete<'r,RetainedCloneStep,crate::OriginalRetirementFailure>,ValueError>{self.close_dispatch(None,body,effect,reply,false)}
 pub fn recover_close_into<'r>(&mut self,body:usize,effect:&mut crate::RetainedAllocationEffect<'_>,reply:crate::native_decoding::OriginalEffectReply<'r,RetainedCloneStep,crate::OriginalRetirementFailure>)->Result<crate::native_decoding::OriginalEffectReplyComplete<'r,RetainedCloneStep,crate::OriginalRetirementFailure>,ValueError>{self.close_dispatch(None,body,effect,reply,true)}
 pub fn close_original_into<'r>(&mut self,original:&mut crate::OriginalRetirementCloseLoan<'_>,body:usize,effect:&mut crate::RetainedAllocationEffect<'_>,reply:crate::native_decoding::OriginalEffectReply<'r,RetainedCloneStep,crate::OriginalRetirementFailure>)->Result<crate::native_decoding::OriginalEffectReplyComplete<'r,RetainedCloneStep,crate::OriginalRetirementFailure>,ValueError>{self.close_dispatch(Some(original),body,effect,reply,false)}
 pub fn recover_close_original_into<'r>(&mut self,original:&mut crate::OriginalRetirementCloseLoan<'_>,body:usize,effect:&mut crate::RetainedAllocationEffect<'_>,reply:crate::native_decoding::OriginalEffectReply<'r,RetainedCloneStep,crate::OriginalRetirementFailure>)->Result<crate::native_decoding::OriginalEffectReplyComplete<'r,RetainedCloneStep,crate::OriginalRetirementFailure>,ValueError>{self.close_dispatch(Some(original),body,effect,reply,true)}
 /// 👶️ Selects the actual matcher or binding original Birth.
 pub fn requires_original_birth(&self)->bool{if let Some(matcher)=self.matcher.as_ref(){return !matcher.terminal_is_empty()&&matcher.requires_original_birth()}RetainedCloneBinding::requires_original_birth(&self.binding)}
 /// 🧵️ Relays the selected original Birth loan.
 pub fn close_original_birth_step(&mut self,original:&mut crate::OriginalRetirementCloseLoan<'_>,grant:RetainedCloneGrant)->crate::OriginalRetirementPoll{if let Some(matcher)=self.matcher.as_mut(){if !matcher.terminal_is_empty()&&matcher.requires_original_birth(){if grant.maximum_items==0||grant.maximum_depth==0{return crate::RetainedWorkPoll::Complete(RetainedWorkOutcome{result:Ok(RetainedCloneStep::Progress(Default::default())),work:0})}return matcher.close_original_birth_step(original,child_grant(grant,0))}}if self.matcher.is_none()&&RetainedCloneBinding::requires_original_birth(&self.binding){return RetainedCloneBinding::close_original_birth_step(&mut self.binding,original,grant)}crate::RetainedWorkPoll::Complete(RetainedWorkOutcome{result:Err(ValueError::literal(crate::ValueRefusalKind::UnsupportedOwner,"variant has no selected original Birth").into()),work:0})}
 /// 🪪️ Reports the selected actual matcher or binding control.
 pub fn requires_original_control(&self)->bool{if let Some(matcher)=self.matcher.as_ref(){return !matcher.terminal_is_empty()&&matcher.requires_original_control()}RetainedCloneBinding::requires_original_control(&self.binding)}
 pub fn terminal_is_empty(&self)->bool{self.binding.is_none()&&self.matcher.is_none()&&(self.phase==6||self.phase==0)}
}
impl<I:NativeValueSource+?Sized>Drop for NativeVariantSelector<I>{fn drop(&mut self){assert!(std::thread::panicking()||self.terminal_is_empty(),"native variant selector requires funded closure")}}
